    a = 1
    b = 1
    while True:
        if max_value is None or a < max_value:
            yield a
            a, b = b, a + b
        else:
            yield max_value


def constant(
    interval: Union[int, Iterable[float]] = 1
) -> Generator[float, None, None]:
    yield  

    try:
        itr = iter(interval)  
    except TypeError:
        itr = itertools.repeat(interval)  

    for val in itr:
        yield val


def runtime(
    *,
    value: Callable[[Any], float]
) -> Generator[float, None, None]:
    ret_or_exc = yield  
    while True:
        ret_or_exc = yield value(ret_or_exc)

